665: function connectionLabel(state: ConnectionStatus["state"] | undefined): string {
666:   if (!state) return "Checking OpenCode";
667:   if (state === "connected") return "OpenCode connected";
668:   if (state === "degraded") return "OpenCode warnings";
669:   if (state === "authentication_required") return "OpenCode auth required";
670:   if (state === "incompatible_version") return "OpenCode incompatible";
671:   if (state === "not_configured") return "OpenCode not configured";
672:   if (state === "checking") return "Checking OpenCode";
673:   return "OpenCode unreachable";
674: }
