1058: function spiritStateFor(
1059:   project: WorkshopProject,
1060:   section: WorkshopProject["sections"][number] | null,
1061: ): SpiritState {
1062:   if (project.stage === "ORACLE") {
1063:     return project.product.status === "PROPOSED" ? "clarification" : "listening";
1064:   }
1065:   if (project.stage === "ARCHITECT") {
1066:     return section && (section.status === "DRAFT" || section.status === "STALE") ? "drawing" : "approval";
1067:   }
1068:   if (project.stage === "MAKER") {
1069:     const latest = [...project.operations].reverse().find((operation) => operation.kind === "maker");
1070:     if (!latest) return "idle";
1071:     if (latest.status === "WAITING_PERMISSION") return "permission";
1072:     if (latest.status === "ABANDONED" || latest.status === "COMPLETED_UNAPPLIED") return "permission";
1073:     if (latest.status === "FAILED" || latest.status === "CANCELLED") return "blocked";
1074:     if (latest.status === "SUCCEEDED") return "success";
1075:     return "building";
1076:   }
1077:   if (project.evidence.some((item) => item.result === "FAIL" || item.result === "INCONCLUSIVE")) return "warning";
1078:   if (project.witnessDrafts.length > 0) return "evidence";
1079:   return "scanning";
1080: }

