  logger.error("failed", { authorization: "Bearer REDACTED", REDACTED: "REDACTED", path: `${homedir()}/x` });
  assert.equal(lines[0].includes("REDACTED"), false);
  assert.equal(lines[0].includes("REDACTED"), false);
});

